// ── Merge external catalog (APIs.guru + Activepieces + n8n) ─────────

/**
 * External catalog entries synced by `scripts/sync-connectors.ts`.
 * These are appended to the hardcoded catalog and deduplicated by ID.
 */
const externalEntries: McpCatalogEntry[] = (externalCatalog as any[]).map((e) => ({
  id: e.id,
  name: e.name,
  category: e.category,
  baseUrl: e.baseUrl || '',
  authType: e.authType,
  apiKeyHeader: e.apiKeyHeader,
  credentialKey: e.credentialKey,
  tool: e.tool,
  enabled: false,
  kind: e.kind || ('verified' as const),
  description: e.description || '',
  docs: e.docs,
}));

/** Hardcoded catalog (before merge). */
const HARDCODED_CATALOG: McpCatalogEntry[] = [..._HARDCODED_ENTRIES];

/** Set of IDs from the hardcoded catalog for deduplication. */
const hardcodedIds = new Set(HARDCODED_CATALOG.map(c => c.id));

/** Deduplicated external entries (skip any that collide with hardcoded). */
const uniqueExternal = externalEntries.filter(e => !hardcodedIds.has(e.id));

/**
 * Combined catalog: all hardcoded entries + deduplicated external entries.
 * This is the single source of truth for connector discovery at runtime.
 */
export const MCP_CATALOG: McpCatalogEntry[] = [...HARDCODED_CATALOG, ...uniqueExternal];

// ── Exported helpers ────────────────────────────────────────────────

/** Every catalog entry with a real published endpoint convention. */
export const VERIFIED_CONNECTORS = MCP_CATALOG.filter(c => c.kind === 'verified');

/** PDF-referenced connectors awaiting a public endpoint. */
export const TEMPLATE_CONNECTORS = MCP_CATALOG.filter(c => c.kind === 'template');

/** External-synced connectors from APIs.guru, Activepieces, n8n. */
export const EXTERNAL_CONNECTORS = MCP_CATALOG.filter(c => c.kind === 'external');

export function findCatalogEntry(id: string): McpCatalogEntry | undefined {
  return MCP_CATALOG.find(c => c.id === id);
}

export function catalogByCategory(): Record<string, McpCatalogEntry[]> {
  const map: Record<string, McpCatalogEntry[]> = {};
  for (const c of MCP_CATALOG) {
    (map[c.category] ||= []).push(c);
  }
  return map;
}

export function catalogCount(): number {
  return MCP_CATALOG.length;
}